import json
import re
import sys

bodyStatus = "invalid"
bodyError = "The VLAN POST body could not be prepared."
bodyResultJson = json.dumps({"error":"VLAN request body preparation failed"}, separators=(",",":"))
postBody = ""
MOID = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._~-]{0,127}$")

def parse_bool(value, label):
    text = str(value).strip().lower()
    if text == "true":
        return True
    if text == "false":
        return False
    raise ValueError(label + " is not a canonical boolean token.")

def relationship(summary, expectedType, expectedName, organizationMoid):
    if not isinstance(summary, dict):
        raise ValueError(expectedType + " validation summary is not an object.")
    required = {"Moid","Name","ClassId","ObjectType","OrganizationMoid"}
    if set(summary) != required:
        raise ValueError(expectedType + " validation summary fields are inconsistent.")
    if not MOID.fullmatch(str(summary.get("Moid",""))) or summary.get("Name") != expectedName:
        raise ValueError(expectedType + " validation summary identity does not match.")
    if summary.get("ClassId") != expectedType or summary.get("ObjectType") != expectedType or summary.get("OrganizationMoid") != organizationMoid:
        raise ValueError(expectedType + " validation summary ownership or discriminators do not match.")
    return summary["Moid"]

try:
    organizationName = sys.argv[1]
    policyName = sys.argv[2]
    vlanName = sys.argv[3]
    vlanId = int(sys.argv[4])
    isNative = parse_bool(sys.argv[5], "Is Native")
    autoUplinks = parse_bool(sys.argv[6], "Auto Allow on Uplinks")
    autoCluster = parse_bool(sys.argv[7], "Auto Allow on Cluster Links")
    sharingType = sys.argv[8]
    primaryVlanId = int(sys.argv[9])
    multicastName = sys.argv[10]
    organizationMoid = sys.argv[11].strip()
    policyMoid = sys.argv[12].strip()
    multicastRequired = parse_bool(sys.argv[13], "Multicast lookup flag")
    multicastSummary = json.loads(sys.argv[14] or "{}")
    primaryRequired = parse_bool(sys.argv[15], "Primary lookup flag")
    primarySummary = json.loads(sys.argv[16] or "{}")
    token = json.loads(sys.argv[17])

    if not MOID.fullmatch(organizationMoid) or not MOID.fullmatch(policyMoid):
        raise ValueError("The exact organization or Ethernet Network Policy Moid is invalid.")
    expectedToken = {
        "Organization":organizationName,
        "PolicyName":policyName,
        "VlanName":vlanName,
        "VlanId":vlanId,
        "IsNative":isNative,
        "AutoAllowOnUplinks":autoUplinks,
        "AutoAllowOnClusterLinks":autoCluster,
        "SharingType":sharingType,
        "PrimaryVlanId":primaryVlanId if primaryRequired else None,
        "MulticastPolicyName":multicastName or None
    }
    if token != expectedToken:
        raise ValueError("The normalized VLAN fields do not match the validated preparation token.")
    if not vlanName or not (1 <= vlanId <= 4093) or sharingType not in ("None","Primary","Isolated","Community"):
        raise ValueError("The normalized VLAN identity or Sharing Type is invalid.")
    if any(ord(ch) < 32 or ord(ch) == 127 or ch in "&?#%+" for ch in vlanName):
        raise ValueError("The normalized VLAN Name contains a control character or unsafe URL query delimiter or encoding metacharacter.")
    if autoCluster and (vlanId == 1 or isNative):
        raise ValueError("Cluster-link auto-allow conflicts with VLAN 1 or native VLAN.")
    if not autoUplinks and autoCluster:
        raise ValueError("Disjoint Layer 2 requires both auto-allow flags false.")
    if vlanId == 1 and not autoUplinks:
        raise ValueError("VLAN 1 cannot be disjoint Layer 2.")

    if primaryRequired:
        if sharingType not in ("Isolated","Community") or not (1 <= primaryVlanId <= 4093) or primaryVlanId == vlanId:
            raise ValueError("The conditional Primary VLAN fields are invalid.")
        requiredPrimary = {"Moid","VlanId","SharingType","ClassId","ObjectType","EthNetworkPolicyMoid"}
        if not isinstance(primarySummary, dict) or set(primarySummary) != requiredPrimary:
            raise ValueError("The Primary VLAN validation summary is incomplete.")
        if not MOID.fullmatch(str(primarySummary.get("Moid",""))) or primarySummary.get("VlanId") != primaryVlanId or primarySummary.get("SharingType") != "Primary" or primarySummary.get("ClassId") != "fabric.Vlan" or primarySummary.get("ObjectType") != "fabric.Vlan" or primarySummary.get("EthNetworkPolicyMoid") != policyMoid:
            raise ValueError("The Primary VLAN validation summary does not match the requested secondary VLAN.")
    elif sharingType in ("Isolated","Community") or primaryVlanId != 0 or primarySummary not in ({},None):
        raise ValueError("Unexpected Primary VLAN state exists for this Sharing Type.")

    multicastMoid = ""
    if multicastRequired:
        if not multicastName:
            raise ValueError("Multicast lookup is required but the normalized name is blank.")
        multicastMoid = relationship(multicastSummary, "fabric.MulticastPolicy", multicastName, organizationMoid)
    elif multicastName or multicastSummary not in ({},None):
        raise ValueError("Unexpected Multicast Policy state exists when no policy was requested.")

    body = {
        "ClassId":"fabric.Vlan",
        "ObjectType":"fabric.Vlan",
        "Name":vlanName,
        "VlanId":vlanId,
        "IsNative":isNative,
        "AutoAllowOnUplinks":autoUplinks,
        "AutoAllowOnClusterLinks":autoCluster,
        "SharingType":sharingType,
        "EthNetworkPolicy":{"ClassId":"mo.MoRef","ObjectType":"fabric.EthNetworkPolicy","Moid":policyMoid}
    }
    if primaryRequired:
        body["PrimaryVlanId"] = primaryVlanId
    if multicastRequired:
        body["MulticastPolicy"] = {"ClassId":"mo.MoRef","ObjectType":"fabric.MulticastPolicy","Moid":multicastMoid}
    requiredKeys = {"ClassId","ObjectType","Name","VlanId","IsNative","AutoAllowOnUplinks","AutoAllowOnClusterLinks","SharingType","EthNetworkPolicy"}
    if set(body) != requiredKeys | ({"PrimaryVlanId"} if primaryRequired else set()) | ({"MulticastPolicy"} if multicastRequired else set()):
        raise ValueError("The VLAN POST body contains unexpected fields.")
    postBody = json.dumps(body, separators=(",",":"))
    bodyStatus = "ready"
    bodyError = ""
    bodyResultJson = json.dumps({"validated":True,"PolicyMoid":policyMoid,"VlanName":vlanName,"VlanId":vlanId,"SharingType":sharingType,"hasPrimaryVlan":primaryRequired,"hasMulticastPolicy":multicastRequired}, separators=(",",":"))
except Exception as exc:
    bodyStatus = "invalid"
    bodyError = "The VLAN POST body failed independent validation: " + str(exc)
    bodyResultJson = json.dumps({"error":"VLAN request body preparation failed","details":bodyError}, separators=(",",":"))
    postBody = ""

import json
import re
import sys

creationStatus = "invalid"
creationError = "The VLAN POST response could not be verified."
creationResultJson = json.dumps({"error":"VLAN create response validation failed","requestMayHaveBeenAccepted":True}, separators=(",",":"))
MOID = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._~-]{0,127}$")

def rel(value, expected):
    if not isinstance(value, dict):
        raise ValueError(expected["ObjectType"] + " response relationship is missing.")
    if str(value.get("Moid","")).strip() != expected["Moid"] or str(value.get("ObjectType","")).strip() != expected["ObjectType"]:
        raise ValueError(expected["ObjectType"] + " response relationship does not match.")
    classId = str(value.get("ClassId","")).strip()
    if classId and classId not in ("mo.MoRef", expected["ObjectType"]):
        raise ValueError(expected["ObjectType"] + " response relationship ClassId is inconsistent.")

try:
    request = json.loads(sys.argv[1])
    response = json.loads(sys.argv[2])
    if not isinstance(request, dict) or not isinstance(response, dict):
        raise ValueError("The request and response must be JSON objects.")
    moid = str(response.get("Moid","")).strip()
    if not MOID.fullmatch(moid):
        raise ValueError("The created VLAN Moid is missing or not URL-safe.")
    if response.get("ClassId") != "fabric.Vlan" or response.get("ObjectType") != "fabric.Vlan":
        raise ValueError("The created VLAN discriminators do not match.")
    for key in ("Name","VlanId","IsNative","AutoAllowOnUplinks","AutoAllowOnClusterLinks","SharingType"):
        if response.get(key) != request.get(key):
            raise ValueError("The created VLAN " + key + " does not match the validated request.")
    rel(response.get("EthNetworkPolicy"), request["EthNetworkPolicy"])
    if "PrimaryVlanId" in request:
        if response.get("PrimaryVlanId") != request["PrimaryVlanId"]:
            raise ValueError("The created VLAN PrimaryVlanId does not match.")
    elif response.get("PrimaryVlanId") not in (None,0):
        raise ValueError("The response unexpectedly contains a nonzero PrimaryVlanId.")
    if "MulticastPolicy" in request:
        rel(response.get("MulticastPolicy"), request["MulticastPolicy"])
    elif response.get("MulticastPolicy") not in (None,{}):
        raise ValueError("The response unexpectedly contains a MulticastPolicy relationship.")
    creationStatus = "exact"
    creationError = ""
    creationResultJson = json.dumps({"created":True,"Moid":moid,"Name":request["Name"],"VlanId":request["VlanId"],"SharingType":request["SharingType"],"EthNetworkPolicyMoid":request["EthNetworkPolicy"]["Moid"],"MulticastPolicyMoid":request.get("MulticastPolicy",{}).get("Moid"),"PrimaryVlanId":request.get("PrimaryVlanId"),"duplicateRaceWindow":True}, separators=(",",":"))
except Exception as exc:
    creationStatus = "invalid"
    creationError = "The VLAN POST may have been accepted, but its response failed verification: " + str(exc)
    creationResultJson = json.dumps({"error":"VLAN create response validation failed","details":creationError,"requestMayHaveBeenAccepted":True}, separators=(",",":"))
